ks_zn = offsets_zn < N // 8\n\n    offsets_sn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)\n    masks_sn = offsets_sn < N\n\n    offsets_k = pid_z * BLOCK_SIZE_K + tl.arange(0, BLOCK_SIZE_K)\n    offsets_a = K * offsets_am[:, None] + offsets_k[None, :]\n    offsets_b = (N // 8) * offsets_k[:, None] + offsets_bn[None, :]\n\n    a_ptrs = a_ptr + offsets_a\n    b_ptrs = b_ptr + offsets_b\n\n    # Pre-load zeros and scales for all groups needed by this thread block\n    start_k = pid_z * BLOCK_SIZE_K\n    end_k = min(start_k + BLOCK_SIZE_K * SPLIT_K, K)\n    start_group = start_k // group_size\n    end_group = (end_k - 1) // group_size + 1\n    num_groups_needed = end_group - start_group\n    \n    # Pre-allocate arrays for zeros and scales\n    zeros_preloaded = tl.zeros((num_groups_needed, BLOCK_SIZE_N // 8), dtype=tl.int32)\n    scales_preloaded = tl.zeros((num_groups_needed, BLOCK_SIZE_N), dtype=scales_ptr.type.element_ty)\n    \n    # Load zeros and scales for all needed groups\n    for g in range(num_groups_needed):\n        group_idx = start_group + g\n        if group_idx < K // group_size:\n            # Load zeros for this group\n            zero_offset = group_idx * (N // 8) + offsets_zn[None, :]\n            zeros_group = tl.load(zeros_ptr + zero_offset, mask=masks_zn[None, :])\n            zeros_preloaded = tl.where(tl.arange(0, num_groups_needed)[:, None] == g, \n                                      zeros_group, zeros_preloaded)\n            \n            # Load scales for this group\n            scale_offset = group_idx * N + offsets_sn[None, :]\n            scales_group = tl.load(scales_ptr + scale_offset, mask=masks_sn[None, :])\n            scales_preloaded = tl.where(tl.arange(0, num_groups_needed)[:, None] == g,\n                                       scales_group, scales_preloaded)\n    \n    # Pre-expand zeros using interleave and broadcast_to\n    zeros_expanded = tl.zeros((num_groups_needed, BLOCK_SIZE_N), dtype=tl.int32)\n    for g in range(num_groups_needed):\n        zeros_group = zeros_preloaded[g, :]\n        # Use interleave to unpack 4-bit values\n        zeros_unpacked = tl.interleave(zeros_group, zeros_group)\n        zeros_unpacked = tl.broadcast_to(zeros_unpacked, (BLOCK_SIZE_N,))\n        zeros_unpacked = (zeros_unpacked >> shifts[0:1, :]) & 0xF\n        zeros_expanded = tl.where(tl.arange(0, num_groups_needed)[:, None] == g,\n                                 zeros_unpacked[None, :], zeros_expanded)\n\n    # NOTE: Use this in TRITON_INTERPRET=1 mode instead of tl.cdiv\n    # block_offset = BLOCK_SIZE_K * SPLIT_K\n    # for k in range(0, (K + block_offset - 1) // (block_offset)):\n    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K * SPLIT_K)):\n        masks_k = offsets_k < K\n        masks_a = masks_am[:, None] & masks_k[None, :]\n        a = tl.load(a_ptrs, mask=masks_a)\n\n        masks_b = masks_k[:, None] & masks_bn[None, :]\n        b = tl.load(b_ptrs, mask=masks_b)\n\n        # Dequantize b using pre-expanded zeros and scales\n        # First unpack b using interleave\n        b_unpacked = tl.interleave(b, b)\n        b_unpacked = tl.broadcast_to(b_unpacked, (BLOCK_SIZE_K, BLOCK_SIZE_N))\n        b_unpacked = (b_unpacked >> shifts) & 0xF\n        \n        if num_groups_needed > 0:\n            # Get group index for each K element\n            current_k_base = BLOCK_SIZE_K * SPLIT_K * k\n            group_indices = (current_k_base + tl.arange(0, BLOCK_SIZE_K)) // group_size - start_group\n            \n            # Create expanded zeros and scales for this K block\n            zeros_block = tl.zeros((BLOCK_SIZE_K, BLOCK_SIZE_N), dtype=tl.int32)\n            scales_block = tl.zeros((BLOCK_SIZE_K, BLOCK_SIZE_N), dtype=scales_ptr.type.element_ty)\n            \n            # For each K element, get the appropriate pre-expanded zeros and scales\n            for i in range(BLOCK_SIZE_K):\n                if i < tl.numel(group_indices):\n                    g_idx = group_indices[i]\n        